def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Find connected components of the two main colors.
    boxes = {1: [], 8: []}
    for color in boxes:
        seen = set()
        for r in range(h):
            for c in range(w):
                if grid[r][c] != color or (r, c) in seen:
                    continue
                stack = [(r, c)]
                seen.add((r, c))
                cells = []
                while stack:
                    y, x = stack.pop()
                    cells.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        yy, xx = y + dy, x + dx
                        if (0 <= yy < h and 0 <= xx < w and
                                grid[yy][xx] == color and (yy, xx) not in seen):
                            seen.add((yy, xx))
                            stack.append((yy, xx))
                rs = [y for y, x in cells]
                cs = [x for y, x in cells]
                boxes[color].append((min(rs), max(rs), min(cs), max(cs)))

    for r in range(h):
        for c in range(w):
            if grid[r][c] in (0, 1, 8):
                continue
            # If inside a target object's bounding box, restore that object color.
            contained = [color for color in (1, 8)
                         if any(a <= r <= b and x <= c <= y
                                for a, b, x, y in boxes[color])]
            if contained:
                out[r][c] = contained[0]
                continue
            # Otherwise restore the nearest existing background/object pixel.
            best = None
            for y in range(h):
                for x in range(w):
                    if grid[y][x] in (0, 1, 8):
                        d = abs(r-y) + abs(c-x)
                        if best is None or d < best[0]:
                            best = (d, grid[y][x])
            out[r][c] = best[1] if best else 0
    return out
